<?php
if($page==='admin-locations'){
  require_admin();$edit=$_GET['edit']??null;$editing=null;if($edit&&$edit!=='new'){$s=$pdo->prepare('SELECT * FROM locations WHERE id=?');$s->execute([(int)$edit]);$editing=$s->fetch();}$list=$pdo->query('SELECT * FROM locations ORDER BY created_at DESC')->fetchAll();layout_start('Manage locations',true);?>
  <section class="container section"><div class="section-head"><div><span class="eyebrow">Inventory</span><h1>Locations</h1></div><a class="btn" href="<?=e(app_url(['page'=>'admin-locations','edit'=>'new']))?>">Add location</a></div><?php if($edit):?><div class="panel"><h2><?=$editing?'Edit location':'New location'?></h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="admin-save-location"><input type="hidden" name="id" value="<?=(int)($editing['id']??0)?>"><div class="two"><label>Name<input name="name" value="<?=e($editing['name']??'')?>" required></label><label>Status<select name="status"><option value="active" <?=($editing['status']??'active')==='active'?'selected':''?>>Active</option><option value="inactive" <?=($editing['status']??'')==='inactive'?'selected':''?>>Inactive</option></select></label></div><label>Address<input name="address" value="<?=e($editing['address']??'')?>" required></label><div class="two"><label>City<input name="city" value="<?=e($editing['city']??'')?>" required></label><label>Country<input name="country" value="<?=e($editing['country']??'')?>" required></label></div><label>Description<textarea name="description" rows="4"><?=e($editing['description']??'')?></textarea></label><label>Opening hours<input name="opening_hours" value="<?=e($editing['opening_hours']??'Daily · 8:00 AM – 10:00 PM')?>"></label><div class="two"><label>Price per bag/day<input name="price_per_bag" type="number" step="0.01" min="0" value="<?=e($editing['price_per_bag']??'5.00')?>"></label><label>Capacity<input name="capacity" type="number" min="1" value="<?=e($editing['capacity']??'20')?>"></label></div><label>Image URL<input name="image_url" type="url" value="<?=e($editing['image_url']??'')?>" placeholder="https://..."></label><div class="actions"><button class="btn" type="submit">Save location</button><a class="btn btn-light" href="<?=e(app_url(['page'=>'admin-locations']))?>">Cancel</a></div></form></div><?php endif;?><div class="panel"><div class="table-wrap"><table><thead><tr><th>Location</th><th>City</th><th>Price</th><th>Capacity</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(!$list):?><tr><td colspan="6">No locations yet.</td></tr><?php else:foreach($list as $l):?><tr><td><strong><?=e($l['name'])?></strong><br><small><?=e($l['address'])?></small></td><td><?=e($l['city'])?></td><td><?=e(money((float)$l['price_per_bag']))?></td><td><?=(int)$l['capacity']?></td><td><span class="status status-<?=e($l['status'])?>"><?=e($l['status'])?></span></td><td><div class="actions"><a class="btn btn-small btn-light" href="<?=e(app_url(['page'=>'admin-locations','edit'=>$l['id']]))?>">Edit</a><form method="post" onsubmit="return confirm('Delete this location?')"><?=csrf_field()?><input type="hidden" name="action" value="admin-delete-location"><input type="hidden" name="id" value="<?=(int)$l['id']?>"><button class="btn btn-small btn-danger" type="submit">Delete</button></form></div></td></tr><?php endforeach;endif;?></tbody></table></div></div></section>
  <?php layout_end();exit;
}
